<?php
namespace App\Http\Controllers;
use App\Models\{Project,ProjectAttachment};use App\Services\{Operations,PrivateFiles};use Illuminate\Http\Request;use Illuminate\Support\Facades\{Gate,DB,Storage};
class FileController extends Controller {
 public function index(Request $r){$query=ProjectAttachment::query()->with(['project:id,title,owner_id,assigned_to'])->whereHas('project',fn($q)=>Operations::projectScope($q,$r->user()));if($r->filled('search'))$query->where('name','like','%'.mb_substr($r->search,0,120).'%');if($r->filled('project_id'))$query->where('project_id',$r->project_id);if($r->filled('type'))$query->where('mime_type','like',mb_substr($r->type,0,80).'%');return $query->latest()->paginate(20);}
 public function upload(Request $r,Project $project,PrivateFiles $files){Gate::authorize('view',$project);abort_unless($r->user()->role==='client'||$r->user()->allows('files'),403);$r->validate(['file'=>'required|file','client_visible'=>'sometimes|boolean']);$attachment=$files->store($r->file('file'),$project,$r->user(),$r->user()->role==='client'?true:$r->boolean('client_visible',true));Operations::notify('file.uploaded','project',$project->id,$project);return response()->json($attachment,201);}
 public function download(Request $r,ProjectAttachment $file){Gate::authorize('view',$file->project);if($r->user()->role==='client')abort_unless($file->client_visible,404);abort_unless(Storage::disk('local')->exists($file->path),404);$headers=['X-Content-Type-Options'=>'nosniff','Cache-Control'=>'private, no-store','Content-Security-Policy'=>"default-src 'none'; sandbox"];
  if($r->boolean('preview')&&str_starts_with($file->mime_type,'image/'))return response()->file(Storage::disk('local')->path($file->path),$headers+['Content-Type'=>$file->mime_type]);return Storage::disk('local')->download($file->path,$file->name,$headers);}
 public function destroy(Request $r,ProjectAttachment $file){Gate::authorize('view',$file->project);abort_unless($r->user()->allows('files'),403);DB::transaction(function()use($r,$file){$file->delete();Operations::log($r->user(),'file.deleted','project',$file->project_id,['file_id'=>$file->id,'name'=>$file->name]);});return ['ok'=>true];}
}
